    $private='/tmp/baize-kernel-'.bin2hex(random_bytes(8));mkdir($private,0700);mkdir($private.'/keys',0700);mkdir($private.'/data',0700);
    $c=['database'=>['dsn'=>'mysql:host=127.0.0.1;port='.$port.';dbname='.$database.';charset=utf8mb4','user'=>'root','password'=>''],'data_dir'=>$private.'/data','key_dir'=>$private.'/keys','public_url'=>'https://analytics.example.test','master_key'=>random_bytes(32)];
    $db=new Database($c);$db->migrate();$db->exec('DELETE FROM documents');$db->exec('DELETE FROM locks');return [$c,$db,$private];
